// EComm — standalone scene 1 (Scene1Map). Transparent background, no scene-level
// fade in/out. Content animates in via its own springs; <Background/> + SceneWrap removed.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "monospace";

// Europe framing — europe.svg keeps only European country paths, viewBox
// "895 55 305 245" in world-map units. Pins map into this same box.
const VB = { x: 895, y: 55, w: 305, h: 245 };
const RED = "#FF3B30";

// The bleeding location — pinned at the centre of the map, larger than the rest.
const BAD = { x: ((1048 - 895) / 305) * 100, y: ((182 - 55) / 245) * 100 };

// Pin icon (Phosphor MapPin, from map-pin.svg) — anchored at its bottom tip.
const PIN_PATH =
  "M128,64a40,40,0,1,0,40,40A40,40,0,0,0,128,64Zm0,64a24,24,0,1,1,24-24A24,24,0,0,1,128,128Zm0-112a88.1,88.1,0,0,0-88,88c0,31.4,14.51,64.68,42,96.25a254.19,254.19,0,0,0,41.45,38.3,8,8,0,0,0,9.18,0A254.19,254.19,0,0,0,174,200.25c27.45-31.57,42-64.85,42-96.25A88.1,88.1,0,0,0,128,16Zm0,206c-16.53-13-72-60.75-72-118a72,72,0,0,1,144,0C200,161.23,144.53,209,128,222Z";

// ~24 European location anchors in world-map units (cluster pins on real land).
const ANCHORS: [number, number][] = [
  [957, 160], [985, 165], [1005, 188], [985, 230], [948, 262], [1016, 175],
  [1060, 160], [1055, 185], [1035, 197], [1075, 190], [1045, 205], [1062, 228],
  [1062, 172], [1090, 158], [1096, 192], [1119, 193], [1132, 221], [1083, 214],
  [1100, 248], [1157, 174], [1088, 110], [1060, 112], [1110, 95], [1048, 145],
];

const Scene1Map: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // 48 pins clustered around the European anchors, mapped from world-map units
  // into the europe.svg viewBox so they land on the visible continent.
  const pins = React.useMemo(() => {
    const arr: { x: number; y: number; seed: string }[] = [];
    let s = 7;
    const rnd = () => {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };
    for (let i = 0; i < 48; i++) {
      const a = ANCHORS[i % ANCHORS.length];
      const wx = a[0] + (rnd() - 0.5) * 16;
      const wy = a[1] + (rnd() - 0.5) * 13;
      arr.push({
        x: ((wx - VB.x) / VB.w) * 100,
        y: ((wy - VB.y) / VB.h) * 100,
        seed: `pin-${i}`,
      });
    }
    return arr;
  }, []);

  const mapIn = springIn(frame, vfps, 4, "LIQUID");
  const mapSc = interpolate(mapIn, [0, 1], [0.94, 1]);
  const mapTy = interpolate(mapIn, [0, 1], [30, 0]);

  // The "problem" pin index — a central (Germany-area) location.
  const badIdx = 6;

  const redTrigger = springIn(frame, vfps, 38, "SNAPPY");

  const driftX = ambientDrift(frame, 2, 110, "map-x");
  const driftY = ambientDrift(frame, 2, 130, "map-y");

  const mapUrl = staticFile("assets/other/europe.svg");

  return (
    <AbsoluteFill>
      {null}
      <AbsoluteFill
        style={{
          padding: base * 0.06,
          opacity: mapIn,
          transform: `translate(${driftX}px, ${mapTy + driftY}px) scale(${mapSc})`,
        }}
      >
        {/* Map only — no card background, no grid (transparent overlay). */}
        <div
          style={{
            position: "absolute",
            inset: `${base * 0.08}px ${base * 0.1}px`,
          }}
        >
          {/* Europe map box — centered at Europe's true aspect (no stretch);
              pins are positioned as % of this box so they land on the continent. */}
          <div
            style={{
              position: "absolute",
              top: 0,
              bottom: 0,
              left: "19.25%",
              width: "61.5%",
            }}
          >
            {/* Recolored map: use the SVG as a CSS mask, fill with COLORS.card
                (the lifted dark Apify surface). This keeps it on-brand and
                stays opaque so it reads correctly over any backdrop. */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: COLORS.card,
                WebkitMaskImage: `url(${mapUrl})`,
                maskImage: `url(${mapUrl})`,
                WebkitMaskRepeat: "no-repeat",
                maskRepeat: "no-repeat",
                WebkitMaskPosition: "center",
                maskPosition: "center",
                WebkitMaskSize: "100% 100%",
                maskSize: "100% 100%",
              }}
            />

            {/* Country borders + coastline — the mask above only keeps the
                silhouette, so the borders are drawn back on top from a
                stroke-only copy of the map. */}
            <div style={{ position: "absolute", inset: 0, opacity: 0.85 }}>
              <Img
                src={staticFile("assets/other/europe-borders.svg")}
                style={{ width: "100%", height: "100%", objectFit: "fill" }}
              />
            </div>

            {/* Pins — map-pin shape, anchored at the tip */}
            {pins.map((pin, i) => {
              const isBad = i === badIdx;
              const pinIn = staggeredSpring(frame, vfps, i, 10, 0.6, "ELASTIC");

              const badGrow = isBad ? redTrigger : 0;
              const size = isBad
                ? base * 0.05 + interpolate(badGrow, [0, 1], [0, base * 0.03])
                : base * 0.03;
              const color = isBad ? RED : COLORS.orange;

              // Red pulse ring on the bleeding location — continues throughout
              const ringScale = isBad ? 1 + ((frame - 38) % 30) / 30 : 1;
              const ringOp = isBad
                ? Math.max(0, 1 - ((frame - 38) % 30) / 30) * 0.5 * badGrow
                : 0;

              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: `${isBad ? BAD.x : pin.x}%`,
                    top: `${isBad ? BAD.y : pin.y}%`,
                    width: size,
                    height: size,
                    transform: `translate(-50%, -88%) scale(${pinIn})`,
                    transformOrigin: "50% 88%",
                    zIndex: isBad ? 10 : 1,
                  }}
                >
                  {isBad && (
                    <div
                      style={{
                        position: "absolute",
                        left: "50%",
                        top: "41%",
                        width: size * 1.5,
                        height: size * 1.5,
                        borderRadius: "50%",
                        background: RED,
                        transform: `translate(-50%, -50%) scale(${ringScale})`,
                        opacity: ringOp,
                      }}
                    />
                  )}
                  <svg
                    viewBox="0 0 256 256"
                    width={size}
                    height={size}
                    style={{
                      position: "relative",
                      display: "block",
                      filter: isBad
                        ? `drop-shadow(0 ${base * 0.004}px ${base * 0.006}px rgba(0,0,0,0.6))`
                        : `drop-shadow(0 ${base * 0.002}px ${base * 0.004}px rgba(0,0,0,0.5))`,
                    }}
                  >
                    <path d={PIN_PATH} fill={color} />
                  </svg>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// =====================================================
// SCENE 2: Report mockup with X over it
